export type SecretarySkill = "services" | "customers" | "scheduling" | "scheduling-batch" | "financial" | "inventory" | "communication";
export function createServicesAgent(model: Model, receive: (patch: ServicePatch | CustomerInterpretation | SchedulingInterpretation | BatchInterpretation | FinancialInterpretation | InventoryInterpretation | CommunicationInterpretation | CapabilitySelection) => void, skill: SecretarySkill | "discovery" = "services") {
  return new Agent({
    name: "Secretária Everflair — Services, Customers, Scheduling e Financial",
    instructions: skill === "discovery" ? discoveryInstructions : loadSkills({ skill_ids: [skill === "scheduling-batch" ? "scheduling" : skill] }).manuals[0].manual,
    model,
    modelSettings: { parallelToolCalls: false, store: false, maxTokens: 1200, preserveRawUsage: true,
      toolChoice: skill === "discovery" ? "select_capabilities" : "upsert_action_draft", retry: { maxRetries: 0 } },
    toolUseBehavior: "stop_on_first_tool",
    tools: [
      tool({ name: skill === "discovery" ? "select_capabilities" : "upsert_action_draft", description: "U03: entrega patch explícito ao backend para validar e atualizar o draft. null omite e preserva.",
        parameters: skill === "discovery" ? selectionSchema : skill === "communication" ? communicationInterpretation : skill === "inventory" ? inventoryInterpretation : skill === "financial" ? financialInterpretation : skill === "scheduling-batch" ? batchInterpretation : skill === "scheduling" ? schedulingInterpretation : skill === "customers" ? customerExtraction : extraction, errorFunction: null, execute: input => {
          if (skill === "discovery") { receive(validateSelection(input)); return "SELECTION_RECEIVED_NOT_EXECUTED"; }
          receive(Object.fromEntries(Object.entries(input).filter(([, v]) => v !== null)));
          return "PATCH_RECEIVED_NOT_EXECUTED";
        } }),
    ],
  });
}

