type Session = { inheritedInterpretation?: boolean; communication?: CommunicationState; inventory?: InventoryState; financial?: FinancialState; batch?: BatchState; scheduling?: SchedulingState; children?: string[]; loaded?: { skill_id: string; version: string; manual_hash: string }[]; skill: "services" | "customers" | "scheduling" | "financial" | "inventory" | "communication" | "auto"; customer?: CustomerState; id: string; actor: ServiceActor; expires: number; busy: boolean; turns: number;
