  private readonly routerTrace = new AsyncLocalStorage<RouterTrace>();
  constructor(private readonly modelFactory: () => Promise<Model>, private readonly modelId: () => string = () => process.env.SALON_SECRETARY_MODEL ?? "unconfigured", private readonly communicationProvider = new FakeCommunicationProvider(), private readonly routerOptions: RouterOptions = {}) {}

