  private view(s: Session): SecretaryView {
    if (s.skill === "auto") return structuredClone({ sessionId: s.id, skill: "auto", cancelled: s.cancelled, loaded: s.loaded,
      message: s.notice ?? (s.children?.length ? "Confira cada operação abaixo. Cada confirmação executa somente sua proposta." : "Posso ajudar com serviços, clientes, agenda, estoque e consultas financeiras. O que deseja?"),
