export const schedulingResolved = z.object({
  ...schedulingFields, appointment_ref:z.string().min(1).max(100), customer_ref: z.string().min(1).max(100), service_ref: z.string().min(1).max(100), professional_ref: z.string().min(1).max(100),
}).partial().strict();
