  const rejectedMissing=rejectedTemporal.filter(r=>(r.field==="time"||r.field==="end_time")&&!f[r.field]);
  if(conflicts.length||rejectedMissing.length){
    c.draft=await withTenant(actor,tx=>upsertSchedulingDraft(tx,actor,{operation:op,fields:f,rejected_temporal:rejectedTemporal,...(c.draft?{draft_ref:c.draft.draft_ref,expected_revision:c.draft.draft_revision}:{})}));
    c.fields=c.draft.fields;
    const pending=[...new Set([...conflicts.map(x=>x.field),...rejectedMissing.map(x=>x.field)])];if(pending.length===1)c.waiting_for=pending[0];
    c.message=[...conflicts,...rejectedMissing].some(x=>x.code==="TIME_OUTSIDE_PERIOD")?"O horário anterior é incompatível com o período informado e foi retirado. Informe o horário exato desejado.":"O final incompatível foi retirado. Informe o horário final correto.";
    return;
  }
