  }
  if(!notice&&!missing.length&&createOrAvailability){
    const availability=await timed(c.metrics,"availability",()=>withTenant(actor,tx=>getSchedulingAvailability(tx,actor,{service_ref:f.service_ref,professional_ref:f.professional_ref,date:f.date,...(f.time?{time:f.time}:{}),...(f.period?{period:f.period}:{})})));
    c.alternatives=availability.alternatives;
    if(op==="appointment.create"&&!availability.plan)notice="Horário indisponível. Escolha uma das alternativas reais ou outro horário.";
    else if(op==="appointment.create")snap=await timed(c.metrics,"availability",()=>withTenant(actor,tx=>schedulingSnapshot(tx,actor,f)));
    else notice=`Horários disponíveis (${availability.timezone}): ${availability.plan?[availability.plan.startLocal,...availability.alternatives.map(s=>s.startLocal)].join(", "):availability.alternatives.map(s=>s.startLocal).join(", ")||"nenhum no intervalo consultado"}. Consulta não reserva horário.`;
  }
