    ...(c.draft?{draft_ref:c.draft.draft_ref,expected_revision:c.draft.draft_revision}:{})}));
  c.fields=c.draft.fields;
  if(notice){c.message=notice;return;}
  if(missing.length){const labels:Record<string,string>={customer_ref:"cliente",service_ref:"serviço",professional_ref:"profissional",date:"data",time:"horário exato",end_time:"horário final",appointment_ref:"agendamento original",reason:"motivo do cancelamento (mínimo 3 caracteres)"};
