export async function selectCommunication(a:ServiceActor,c:CommunicationState,ref:string){
  if(c.receipt)throw Error("ALREADY_CONFIRMED");
  if(c.cancel?.candidates){await selectScheduling(a,c.cancel,ref);await prepare(a,c);return;}
